  ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = '#fff';
  ctx.textAlign = 'center';
  ctx.font = 'bold 28px system-ui'; ctx.fillText('Game Over', w/2, h/2 - 12);
  ctx.font = '16px system-ui';      ctx.fillText('Score ' + score + ' - press any key', w/2, h/2 + 18);
}
